export const NEIGHBOR_SIDES=['north','east','south','west','sea'];
export function freshNeighborEconomies(month=0){return Object.fromEntries(NEIGHBOR_SIDES.map((side,i)=>[side,{population:[8000,12000,6000,10000,0][i],treasury:200000,powerCapacity:1500,waterCapacity:1200,wasteCapacity:side==='sea'?100000:10000,wasteStored:side==='sea'?30000:3000,month,lastTradeBalance:0}]));}
export function validateNeighborEconomies(v,month){if(v===undefined)return freshNeighborEconomies(month);if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).length!==5)throw Error('Invalid neighboring cities.');return Object.fromEntries(NEIGHBOR_SIDES.map(side=>{const n=v[side];if(!n||!Number.isFinite(n.population)||n.population<0||n.population>1000000||side==='sea'&&n.population!==0||!Number.isFinite(n.treasury)||Math.abs(n.treasury)>1e12||!Number.isInteger(n.month)||n.month<0||n.month>month||!Number.isFinite(n.lastTradeBalance)||Math.abs(n.lastTradeBalance)>1e9||!['powerCapacity','waterCapacity','wasteCapacity'].every(k=>Number.isFinite(n[k])&&n[k]>=0&&n[k]<=1e7)||!Number.isFinite(n.wasteStored)||n.wasteStored<0||n.wasteStored>n.wasteCapacity)throw Error('Invalid neighboring city economy.');return[side,Object.fromEntries(['population','treasury','powerCapacity','waterCapacity','wasteCapacity','wasteStored','month','lastTradeBalance'].map(k=>[k,n[k]]))];}));}
export function neighborSupply(c,side,kind){const n=c.region.neighbors[side];if(kind==='garbage')return Math.max(0,n.wasteCapacity-n.wasteStored-Math.max(0,n.population*.005-(side==='sea'?100:20)));return Math.max(0,n[kind+'Capacity']-n.population*(kind==='power'?.04:.035));}
export function advanceNeighborEconomies(c,deals,connections=[]){for(const side of NEIGHBOR_SIDES){const n=c.region.neighbors[side];if(n.month>=c.month)continue;let tradeBalance=0,powerOut=0,waterOut=0,powerIn=0,waterIn=0,wasteIn=0,wasteOut=0;for(const d of deals){if(d.failed||c.region.connections[d.connection].side!==side)continue;const cityBuys=d.kind==='garbage'?d.direction==='export':d.direction==='import';const payment=cityBuys?Math.max(d.minFee,d.delivered*d.rate):d.delivered*d.rate;tradeBalance+=cityBuys?payment:-payment;if(d.kind==='garbage'){if(d.direction==='export')wasteIn+=d.delivered;else wasteOut+=d.delivered;}else if(d.kind==='power'){if(d.direction==='import')powerOut+=d.delivered;else powerIn+=d.delivered;}else{if(d.direction==='import')waterOut+=d.delivered;else waterIn+=d.delivered;}}
 n.lastTradeBalance=Math.round(tradeBalance);n.treasury=Math.max(-1e12,Math.min(1e12,n.treasury+n.population*.08-n.powerCapacity*.02-n.waterCapacity*.015+n.lastTradeBalance));
 n.wasteStored=Math.max(0,Math.min(n.wasteCapacity,n.wasteStored+wasteIn-wasteOut+n.population*.005-(side==='sea'?100:20)));
 if(side!=='sea'){const powerNeed=n.population*.04,waterNeed=n.population*.035,shortage=n.powerCapacity+powerIn-powerOut<powerNeed||n.waterCapacity+waterIn-waterOut<waterNeed||n.wasteStored>=n.wasteCapacity;const linked=connections.some(p=>p.side===side);n.population=Math.max(0,Math.min(1000000,n.population*(1+(shortage?-.002:linked?.0012:.001))));
 // Local tax receipts finance capacity expansions; no money is taken from the player's treasury.
 for(const [key,used,cost,amount]of [['powerCapacity',powerNeed+powerOut-powerIn,12000,300],['waterCapacity',waterNeed+waterOut-waterIn,10000,250],['wasteCapacity',n.wasteStored,8000,2000]])if(n[key]<1e7&&used>=n[key]*.8&&n.treasury>=cost){n.treasury-=cost;n[key]=Math.min(1e7,n[key]+amount);}}
 n.month=c.month;
}}
